const envelope = $input.first().json;
if (envelope.execution_mode !== 'OFFLINE_EVAL' || envelope.external_effects_allowed !== false) throw new Error('WF-04 aceita somente OFFLINE_EVAL');
if (!envelope.routing_registration?.routing_id) throw new Error('Roteamento não persistido');
const selected = envelope.routing?.selected_domains ?? [];
if (selected.length > 4) throw new Error('Orçamento excedido: mais de quatro Gerentes Gerais');
if (!selected.length) return [{ json: { skip: true } }];
return selected.map((entry) => ({ json: {
  domain: entry.domain, capabilities: entry.capabilities,
  context: { execution_mode: envelope.execution_mode, external_effects_allowed: false, event_id: envelope.registration.event_id, routing_id: envelope.routing_registration.routing_id, trace_id: envelope.trace_id, run_id: envelope.run_id, correlation_id: envelope.correlation_id, input_hash: envelope.input_hash, received_at: envelope.event.received_at, subject_ref: envelope.event.subject_ref, data_classification: envelope.event.data_classification, untrusted_text_excerpt: String(envelope.payload.text ?? '').slice(0, 1000), files: (envelope.payload.files ?? []).map(({ file_name, mime_type, size_bytes, sha256, content_trust }) => ({ file_name, mime_type, size_bytes, sha256, content_trust })) }
} }));

const envelope = $('Receber decisão roteada').first().json;
const outputs = $input.all().map((item) => item.json).filter((item) => item.skip !== true);
const handoffs = outputs.map((item) => item.domain_handoff);
const expected = envelope.routing?.selected_domains?.length ?? 0;
if (handoffs.length !== expected) throw new Error(`Quantidade de handoffs divergente: esperados ${expected}, recebidos ${handoffs.length}`);
if (new Set(handoffs.map((handoff) => handoff.domain)).size !== handoffs.length) throw new Error('Gerente Geral duplicado para o mesmo domínio');
return [{ json: { ...envelope, domain_handoffs: handoffs, manager_execution: { status: expected ? 'COMPLETED' : 'NOT_REQUIRED', managers_requested: expected, managers_completed: handoffs.length, implementations: outputs.map(({ domain, manager_implementation, capabilities_executed }) => ({ domain, manager_implementation, capabilities_executed })) } } }];
